<script>const list=document.getElementById('task-list'),statusMessage=document.getElementById('save-status');if(list&&window.Sortable&&list.querySelector('[data-id]'))new Sortable(list,{handle:'.drag-handle',animation:150,onEnd:async()=>{const taskIds=[...list.querySelectorAll('[data-id]')].map(x=>Number(x.dataset.id));list.querySelectorAll('[data-id]').forEach((x,i)=>x.querySelector('.priority').textContent=i+1);statusMessage.textContent='Saving order…';try{const r=await fetch('{{ route('tasks.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({project_id:Number(list.dataset.projectId),task_ids:taskIds})});if(!r.ok)throw new Error('Could not save order.');statusMessage.textContent='Order saved successfully.'}catch(e){statusMessage.textContent=e.message+' Refresh and try again.'}}});</script></body></html>
